const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');

const { logger } = require('./config/logger');
const authRoutes = require('./routes/auth.routes');
const profileRoutes = require('./routes/profile.routes');
const policyRoutes = require('./routes/policy.routes');
const purchaseRoutes = require('./routes/purchase.routes');
const renewalRoutes = require('./routes/renewal.routes');

const app = express();

// Security middleware
app.use(helmet());

// CORS configuration
app.use(cors({
  origin: ['http://localhost:3000', 'http://127.0.0.1:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting for authentication endpoints (disabled for development)
if (process.env.NODE_ENV === 'production') {
  const authLimiter = rateLimit({
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
    max: parseInt(process.env.RATE_LIMIT_MAX_ATTEMPTS) || 5, // limit each IP to 5 requests per windowMs
    message: {
      error: 'Too many authentication attempts, please try again later.',
      retryAfter: '15 minutes'
    },
    standardHeaders: true,
    legacyHeaders: false,
  });

  // Apply rate limiting to auth routes only in production
  app.use('/api/auth', authLimiter);
} else {
  // Development: More lenient rate limiting
  const devAuthLimiter = rateLimit({
    windowMs: 1 * 60 * 1000, // 1 minute
    max: 100, // 100 requests per minute in development
    message: {
      error: 'Too many authentication attempts, please try again later.',
      retryAfter: '1 minute'
    },
    standardHeaders: true,
    legacyHeaders: false,
  });

  app.use('/api/auth', devAuthLimiter);
}

// Body parsing middleware
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true }));

// Logging middleware
app.use(morgan('combined', { stream: { write: message => logger.info(message.trim()) } }));

// Routes
app.use('/api/auth', authRoutes);
app.use('/api/profile', profileRoutes);
app.use('/api/policies', policyRoutes);
app.use('/api/purchases', purchaseRoutes);
app.use('/api/renewals', renewalRoutes);

// Health check endpoint
app.get('/api/health', (req, res) => {
  res.status(200).json({
    status: 'OK',
    timestamp: new Date().toISOString(),
    service: 'InsureMithra API',
    version: '1.0.0'
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', error);
  
  res.status(error.status || 500).json({
    error: error.message || 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

module.exports = app;

const Claim = require('../models/claim.model');
const Purchase = require('../models/purchase.model');
const User = require('../models/user.model');
const generateClaimId = require('../utils/claimIdGenerator');
const storageService = require('../services/storage.service');
const { logger } = require('../config/logger');
const fs = require('fs');
const path = require('path');
const { sendClaimStatusEmail } = require('../utils/claimStatusNotifier');

// Create logs directory if it doesn't exist
const logsDir = path.join(process.cwd(), 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

const claimsLogPath = path.join(logsDir, 'claims.log');

/**
 * Log claim submission to claims.log
 */
function logClaimSubmission(userId, claimId, policyId, ipAddress) {
  const logEntry = JSON.stringify({
    timestamp: new Date().toISOString(),
    userId: userId.toString(),
    claimId,
    policyId: policyId.toString(),
    ip: ipAddress,
    action: 'CLAIM_SUBMITTED'
  }) + '\n';

  fs.appendFileSync(claimsLogPath, logEntry, 'utf8');
}

/**
 * Log status changes to claims.log
 */
function logStatusChange(claimId, newStatus, updatedBy) {
  const entry = `[${new Date().toISOString()}] claimId=${claimId}, status=${newStatus}, updatedBy=${updatedBy}\n`;
  try {
    fs.appendFileSync(claimsLogPath, entry, 'utf8');
  } catch (err) {
    logger.error('Failed to write status change to claims.log', err);
  }
}

/**
 * POST /api/claims
 * Submit a new insurance claim with documents
 */
const submitClaim = async (req, res) => {
  try {
    const userId = req.user?._id;
    if (!userId) {
      return res.status(401).json({ success: false, message: 'Unauthorized' });
    }

    const { policyId, reason } = req.body;
    const files = req.files;

    // Validation
    if (!policyId) {
      return res.status(400).json({ success: false, message: 'policyId is required' });
    }

    if (!reason || reason.trim().length === 0) {
      return res.status(400).json({ success: false, message: 'reason is required' });
    }

    if (!files || files.length === 0) {
      return res.status(400).json({ success: false, message: 'At least one document is required' });
    }

    // Verify policy ownership - check if user has purchased this policy
    const purchase = await Purchase.findOne({ userId, policyId, status: 'success' });
    if (!purchase) {
      return res.status(403).json({ 
        success: false, 
        message: 'You can only submit claims for policies you have purchased' 
      });
    }

    // Generate unique claim ID
    const claimId = generateClaimId();

    // Store documents
    let documentMetadata;
    try {
      documentMetadata = await storageService.storeClaimDocuments(claimId, files);
    } catch (storageError) {
      logger.error('Error storing claim documents:', storageError);
      return res.status(500).json({ 
        success: false, 
        message: 'Failed to store claim documents', 
        error: storageError.message 
      });
    }

    // Create claim record
    const claim = new Claim({
      claimId,
      userId,
      policyId,
      reason: reason.trim(),
      documents: documentMetadata,
      status: 'Submitted',
      audit: {
        ipAddress: req.ip || req.connection.remoteAddress,
        userAgent: req.get('user-agent'),
        submissionLocation: req.get('x-forwarded-for') || req.connection.remoteAddress
      }
    });

    await claim.save();

    // Log the submission
    logClaimSubmission(userId, claimId, policyId, claim.audit.ipAddress);

    logger.info(`Claim submitted successfully: ${claimId} by user ${userId}`);

    return res.status(200).json({
      success: true,
      claimId,
      message: 'Claim submitted successfully. You will be notified about the status.',
      data: {
        claimId,
        status: claim.status,
        submittedAt: claim.submittedAt,
        documentCount: documentMetadata.length
      }
    });

  } catch (error) {
    logger.error('Error submitting claim:', error);
    return res.status(500).json({ 
      success: false, 
      message: 'Error submitting claim', 
      error: error.message 
    });
  }
};

/**
 * GET /api/claims
 * Get all claims for the authenticated user
 */
const getUserClaims = async (req, res) => {
  try {
    const userId = req.user?._id;
    if (!userId) {
      return res.status(401).json({ success: false, message: 'Unauthorized' });
    }

    const claims = await Claim.find({ userId })
      .populate('policyId', 'name type insurer premium')
      .sort({ submittedAt: -1 });

    // Return minimal fields for list view
    const mapped = claims.map(c => ({
      _id: c._id,
      claimId: c.claimId,
      policyId: c.policyId,
      status: c.status,
      submittedAt: c.submittedAt,
      updatedAt: c.updatedAt,
      documents: c.documents || [],
      notes: c.notes || ''
    }));

    return res.status(200).json({
      success: true,
      count: mapped.length,
      data: mapped
    });

  } catch (error) {
    logger.error('Error fetching user claims:', error);
    return res.status(500).json({ 
      success: false, 
      message: 'Error fetching claims', 
      error: error.message 
    });
  }
};

/**
 * GET /api/claims/:claimId
 * Get details of a specific claim
 */
const getClaimById = async (req, res) => {
  try {
    const userId = req.user?._id;
    const { claimId, id } = req.params;
    const lookupId = claimId || id;

    if (!userId) {
      return res.status(401).json({ success: false, message: 'Unauthorized' });
    }

    const claim = await Claim.findOne({ claimId: lookupId })
      .populate('policyId', 'name type insurer premium coverage')
      .populate('userId', 'firstName lastName email');

    if (!claim) {
      return res.status(404).json({ success: false, message: 'Claim not found' });
    }

    // Verify ownership (or admin access)
    if (claim.userId._id.toString() !== userId.toString() && req.user.role !== 'admin') {
      return res.status(403).json({ success: false, message: 'Access denied' });
    }

    return res.status(200).json({
      success: true,
      data: claim
    });

  } catch (error) {
    logger.error('Error fetching claim:', error);
    return res.status(500).json({ 
      success: false, 
      message: 'Error fetching claim details', 
      error: error.message 
    });
  }
};

/**
 * GET /api/claims/:claimId/documents/:filename
 * Returns a document file for a claim if the requester is the owner or admin
 */
const getClaimByIdDocument = async (req, res) => {
  try {
    const userId = req.user?._id;
    const { claimId, filename } = req.params;

    if (!userId) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const claim = await Claim.findOne({ claimId }).populate('userId', 'email');
    if (!claim) return res.status(404).json({ success: false, message: 'Claim not found' });

    // Ownership or admin check
    if (claim.userId._id.toString() !== userId.toString() && req.user.role !== 'admin') {
      return res.status(403).json({ success: false, message: 'Access denied' });
    }

    const matched = (claim.documents || []).find(d => d.filename === filename);
    if (!matched) return res.status(404).json({ success: false, message: 'Document not found' });

    // Use absolute path saved in metadata
    const filePath = matched.path;
    if (!filePath || !fs.existsSync(filePath)) {
      return res.status(404).json({ success: false, message: 'File missing on server' });
    }

    return res.sendFile(path.resolve(filePath));
  } catch (error) {
    logger.error('Error fetching claim document:', error);
    return res.status(500).json({ success: false, message: 'Error fetching document', error: error.message });
  }
};

/**
 * PUT /api/claims/:id/status
 * Admin endpoint to update claim status
 */
const updateClaimStatus = async (req, res) => {
  try {
    const user = req.user;
    if (!user || user.role !== 'admin') {
      return res.status(403).json({ success: false, message: 'Access denied' });
    }

    const { id } = req.params;
    const { status, note } = req.body;

    const allowed = ['Submitted', 'Under Review', 'Approved', 'Rejected', 'Closed'];
    if (!status || !allowed.includes(status)) {
      return res.status(400).json({ success: false, message: 'Invalid status' });
    }

    const claim = await Claim.findOne({ claimId: id });
    if (!claim) return res.status(404).json({ success: false, message: 'Claim not found' });

    const previous = claim.status;
    claim.status = status;
    claim.history = claim.history || [];
    claim.history.push({ status, updatedAt: new Date(), note: note || '', updatedBy: user._id });
    claim.lastUpdatedBy = user._id;
    claim.updatedAt = Date.now();

    await claim.save();

    // Log to claims.log
    logStatusChange(claim.claimId, status, user.email || user._id);

    // Notify user by email (best-effort)
    try {
      const claimOwner = await User.findById(claim.userId);
      if (claimOwner && claimOwner.email) {
        await sendClaimStatusEmail(claimOwner.email, claim.claimId, status);
      }
    } catch (emailErr) {
      logger.error('Error sending claim status email:', emailErr);
    }

    return res.status(200).json({ success: true, message: 'Status updated', data: { claimId: claim.claimId, status } });

  } catch (error) {
    logger.error('Error updating claim status:', error);
    return res.status(500).json({ success: false, message: 'Failed to update status', error: error.message });
  }
};

/**
 * GET /api/claims/admin
 * Admin-only: list all claims with optional pagination and filters
 */
const getAllClaimsAdmin = async (req, res) => {
  try {
    const user = req.user;
    if (!user || user.role !== 'admin') {
      return res.status(403).json({ success: false, message: 'Access denied' });
    }

    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 50;
    const skip = (page - 1) * limit;

    const filter = {};
    if (req.query.status) filter.status = req.query.status;
    if (req.query.userEmail) {
      // simple search by user email - will populate and filter in-memory fallback
    }

    const [claims, total] = await Promise.all([
      Claim.find(filter)
        .populate('policyId', 'name type insurer')
        .populate('userId', 'firstName lastName email')
        .sort({ submittedAt: -1 })
        .skip(skip)
        .limit(limit),
      Claim.countDocuments(filter)
    ]);

    const mapped = claims.map(c => ({
      _id: c._id,
      claimId: c.claimId,
      policy: c.policyId,
      user: c.userId,
      status: c.status,
      submittedAt: c.submittedAt,
      updatedAt: c.updatedAt,
      documentCount: (c.documents || []).length,
      lastUpdatedBy: c.lastUpdatedBy
    }));

    return res.status(200).json({ success: true, count: mapped.length, total, page, limit, data: mapped });
  } catch (error) {
    logger.error('Error listing claims for admin:', error);
    return res.status(500).json({ success: false, message: 'Failed to list claims', error: error.message });
  }
};

module.exports = {
  submitClaim,
  getUserClaims,
  getClaimById,
  getClaimByIdDocument,
  updateClaimStatus,
  getAllClaimsAdmin
};

const Purchase = require('../models/purchase.model');
const Policy = require('../models/policy.model');
const User = require('../models/user.model');
const generateTransactionId = require('../utils/generateTransactionId');
const generatePolicyPDF = require('../utils/generatePolicyPDF');
const { logger } = require('../config/logger');
const { calculateNewExpiry } = require('../utils/renewalCalculator');

// POST /api/purchase/initiate
// Body: { policyId }
const initiatePurchase = async (req, res) => {
  try {
    const userId = req.user && req.user._id;
    if (!userId) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const { policyId } = req.body;
    if (!policyId) return res.status(400).json({ success: false, message: 'policyId is required' });

    const policy = await Policy.findById(policyId);
    if (!policy) return res.status(404).json({ success: false, message: 'Policy not found' });

    const transactionId = generateTransactionId('TX_');
    const purchase = new Purchase({ userId, policyId, transactionId, status: 'initiated', amount: policy.premium });
    await purchase.save();

    // Simulate processing asynchronously
    process.nextTick(() => simulateProcessing(purchase._id));

    return res.status(201).json({ success: true, message: 'Purchase initiated', data: { purchaseId: purchase._id, transactionId } });
  } catch (err) {
    logger.error('Error initiating purchase:', err);
    return res.status(500).json({ success: false, message: 'Error initiating purchase', error: err.message });
  }
};

// POST /api/purchase/complete
// Body: { purchaseId }
const completePurchase = async (req, res) => {
  try {
    const userId = req.user && req.user._id;
    if (!userId) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const { purchaseId } = req.body;
    if (!purchaseId) return res.status(400).json({ success: false, message: 'purchaseId is required' });

    const purchase = await Purchase.findById(purchaseId);
    if (!purchase) return res.status(404).json({ success: false, message: 'Purchase not found' });
    if (purchase.userId.toString() !== userId.toString()) return res.status(403).json({ success: false, message: 'Forbidden' });

    // If already processed
    if (purchase.status === 'success') return res.status(200).json({ success: true, message: 'Already completed', data: purchase });
    if (purchase.status === 'failed') return res.status(400).json({ success: false, message: 'Purchase already failed' });

    // Mark success and generate policy number + PDF
    purchase.status = 'processing';
    await purchase.save();

    const policy = await Policy.findById(purchase.policyId);
    const user = await User.findById(purchase.userId);

    purchase.policyNumber = `POL${Date.now()}`;
    purchase.status = 'success';

    // Calculate expiry date based on policy tenure
    const startDate = new Date();
    purchase.expiryDate = calculateNewExpiry(startDate, policy.tenure || '1 year');
    purchase.renewalStatus = 'active';

    // Generate PDF
    try {
      const pdfPath = await generatePolicyPDF({ purchase, user, policy });
      purchase.pdfPath = pdfPath;
    } catch (pdfErr) {
      logger.error('PDF generation failed:', pdfErr);
      // allow purchase to be success even if pdf fails
    }

    await purchase.save();

    return res.status(200).json({ success: true, message: 'Purchase completed', data: purchase });
  } catch (err) {
    logger.error('Error completing purchase:', err);
    return res.status(500).json({ success: false, message: 'Error completing purchase', error: err.message });
  }
};

// GET /api/purchase/:id
const getPurchase = async (req, res) => {
  try {
    const userId = req.user && req.user._id;
    const { id } = req.params;
    const purchase = await Purchase.findById(id);
    if (!purchase) return res.status(404).json({ success: false, message: 'Purchase not found' });
    if (!userId || purchase.userId.toString() !== userId.toString()) return res.status(403).json({ success: false, message: 'Forbidden' });
    return res.status(200).json({ success: true, data: purchase });
  } catch (err) {
    logger.error('Error fetching purchase:', err);
    return res.status(500).json({ success: false, message: 'Error fetching purchase', error: err.message });
  }
};

// GET /api/purchase/:id/download
const downloadPDF = async (req, res) => {
  try {
    const userId = req.user && req.user._id;
    const { id } = req.params;
    const purchase = await Purchase.findById(id);
    if (!purchase) return res.status(404).json({ success: false, message: 'Purchase not found' });
    if (!userId || purchase.userId.toString() !== userId.toString()) return res.status(403).json({ success: false, message: 'Forbidden' });
    if (!purchase.pdfPath) return res.status(404).json({ success: false, message: 'PDF not available yet' });

    return res.sendFile(purchase.pdfPath);
  } catch (err) {
    logger.error('Error downloading PDF:', err);
    return res.status(500).json({ success: false, message: 'Error downloading PDF', error: err.message });
  }
};

// Simulate asynchronous processing with random delay 10-30s, fail if >120s from creation
async function simulateProcessing(purchaseId) {
  try {
    const purchase = await Purchase.findById(purchaseId);
    if (!purchase) return;

    // random delay
    const delay = 10000 + Math.floor(Math.random() * 20000); // 10-30s

    // if already processed, skip
    if (purchase.status !== 'initiated') return;

    // mark processing
    purchase.status = 'processing';
    await purchase.save();

    setTimeout(async () => {
      const now = Date.now();
      const created = new Date(purchase.createdAt).getTime();
      if ((now - created) > 120000) {
        purchase.status = 'failed';
        await purchase.save();
        return;
      }

      // complete purchase
      purchase.policyNumber = `POL${Date.now()}`;
      purchase.status = 'success';

      // Calculate expiry date based on policy tenure
      const startDate = new Date();
      purchase.expiryDate = calculateNewExpiry(startDate, policy.tenure || '1 year');
      purchase.renewalStatus = 'active';

      const user = await User.findById(purchase.userId);
      try {
        const pdfPath = await generatePolicyPDF({ purchase, user, policy });
        purchase.pdfPath = pdfPath;
      } catch (pdfErr) {
        logger.error('PDF generation failed during simulateProcessing:', pdfErr);
      }

      await purchase.save();
    }, delay);
  } catch (err) {
    logger.error('simulateProcessing error:', err);
  }
}

/**
 * GET /api/purchase/my
 * Get all purchases for the authenticated user
 */
const getUserPurchases = async (req, res) => {
  try {
    const userId = req.user && req.user._id;
    if (!userId) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const purchases = await Purchase.find({ userId })
      .populate('policyId', 'name type insurer premium model coverage')
      .sort({ createdAt: -1 });

    return res.status(200).json({ 
      success: true, 
      count: purchases.length,
      data: purchases 
    });
  } catch (err) {
    logger.error('Error fetching user purchases:', err);
    return res.status(500).json({ success: false, message: 'Error fetching purchases', error: err.message });
  }
};

/**
 * POST /api/purchase/create-test-purchase
 * Create a test purchase with expiry date within 7 days (for testing renewal feature)
 * Body: { policyId, daysUntilExpiry }
 */
const createTestPurchase = async (req, res) => {
  try {
    const userId = req.user && req.user._id;
    if (!userId) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const { policyId, daysUntilExpiry = 5 } = req.body;
    if (!policyId) return res.status(400).json({ success: false, message: 'policyId is required' });

    const policy = await Policy.findById(policyId);
    if (!policy) return res.status(404).json({ success: false, message: 'Policy not found' });

    // Create a purchase that's already successful
    const transactionId = generateTransactionId('TX_TEST_');
    const policyNumber = `POL_TEST_${Date.now()}`;
    
    // Calculate expiry date
    const expiryDate = new Date();
    expiryDate.setDate(expiryDate.getDate() + parseInt(daysUntilExpiry));

    const purchase = new Purchase({
      userId,
      policyId,
      transactionId,
      policyNumber,
      status: 'success',
      amount: policy.premium,
      currency: 'INR',
      expiryDate,
      renewalStatus: 'active',
      createdAt: new Date(),
      updatedAt: new Date()
    });

    await purchase.save();

    const populatedPurchase = await Purchase.findById(purchase._id)
      .populate('policyId', 'name type insurer premium model coverage tenure');

    return res.status(201).json({
      success: true,
      message: `Test purchase created with expiry in ${daysUntilExpiry} days`,
      data: populatedPurchase
    });
  } catch (err) {
    logger.error('Error creating test purchase:', err);
    return res.status(500).json({ success: false, message: 'Error creating test purchase', error: err.message });
  }
};

module.exports = { 
  initiatePurchase, 
  completePurchase, 
  getPurchase, 
  downloadPDF, 
  getUserPurchases,
  createTestPurchase 
};

const Purchase = require('../models/purchase.model');
const Policy = require('../models/policy.model');
const Renewal = require('../models/renewal.model');
const { logger } = require('../config/logger');
const { calculateDaysUntilExpiry, isEligibleForRenewal, calculateNewExpiry } = require('../utils/renewalCalculator');
const { generateTransactionId } = require('../utils/transactionId');
const { processPayment } = require('../services/payment.service');
const { sendEmail } = require('../config/mailer');
const fs = require('fs').promises;
const path = require('path');

const RENEWAL_WINDOW_DAYS = parseInt(process.env.RENEWAL_WINDOW_DAYS) || 7;

/**
 * Check renewal eligibility for a purchase
 * GET /api/renewals/eligibility/:purchaseId
 */
const checkEligibility = async (req, res) => {
  try {
    const { purchaseId } = req.params;
    const userId = req.user._id || req.user.id;

    // Find purchase and populate policy details
    const purchase = await Purchase.findById(purchaseId).populate('policyId');
    
    if (!purchase) {
      return res.status(404).json({
        error: 'Purchase not found',
        code: 'PURCHASE_NOT_FOUND'
      });
    }

    // Verify user owns this purchase
    if (purchase.userId.toString() !== userId.toString()) {
      return res.status(403).json({
        error: 'You do not have permission to renew this policy',
        code: 'UNAUTHORIZED_RENEWAL'
      });
    }

    // Check if purchase has expiry date
    if (!purchase.expiryDate) {
      return res.status(400).json({
        error: 'This purchase does not have an expiry date set',
        code: 'NO_EXPIRY_DATE'
      });
    }

    const daysLeft = calculateDaysUntilExpiry(purchase.expiryDate);
    const eligible = isEligibleForRenewal(purchase.expiryDate, RENEWAL_WINDOW_DAYS);
    
    // Calculate renewal amount (same as original premium for now)
    const renewalAmount = purchase.policyId.premium;

    logger.info(`Eligibility check for purchase ${purchaseId}: eligible=${eligible}, daysLeft=${daysLeft}`);

    res.json({
      eligible,
      purchaseId: purchase._id,
      policyName: purchase.policyId.name,
      policyType: purchase.policyId.type,
      expiryDate: purchase.expiryDate,
      daysLeft: Math.max(0, daysLeft),
      renewalAmount,
      currency: purchase.currency,
      renewalWindowDays: RENEWAL_WINDOW_DAYS,
      message: eligible 
        ? 'Your policy is eligible for renewal' 
        : `Renewal will be available ${RENEWAL_WINDOW_DAYS} days before expiry`
    });

  } catch (error) {
    logger.error('Eligibility check error:', error);
    res.status(500).json({
      error: 'Failed to check renewal eligibility',
      code: 'ELIGIBILITY_CHECK_ERROR'
    });
  }
};

/**
 * Initiate renewal process
 * POST /api/renewals/initiate
 */
const initiateRenewal = async (req, res) => {
  try {
    const { purchaseId, paymentMethod } = req.body;
    const userId = req.user._id || req.user.id;

    if (!purchaseId || !paymentMethod) {
      return res.status(400).json({
        error: 'Purchase ID and payment method are required',
        code: 'MISSING_REQUIRED_FIELDS'
      });
    }

    // Find purchase and populate policy
    const purchase = await Purchase.findById(purchaseId).populate('policyId');
    
    if (!purchase) {
      return res.status(404).json({
        error: 'Purchase not found',
        code: 'PURCHASE_NOT_FOUND'
      });
    }

    // Verify ownership
    if (purchase.userId.toString() !== userId.toString()) {
      return res.status(403).json({
        error: 'You do not have permission to renew this policy',
        code: 'UNAUTHORIZED_RENEWAL'
      });
    }

    // Check eligibility
    if (!isEligibleForRenewal(purchase.expiryDate, RENEWAL_WINDOW_DAYS)) {
      const daysLeft = calculateDaysUntilExpiry(purchase.expiryDate);
      return res.status(400).json({
        error: `Renewal not yet available. Renewal window opens ${RENEWAL_WINDOW_DAYS} days before expiry.`,
        code: 'NOT_ELIGIBLE',
        daysLeft: Math.max(0, daysLeft)
      });
    }

    // Check for existing pending renewal
    const existingRenewal = await Renewal.findOne({
      purchaseId,
      status: { $in: ['initiated', 'processing'] }
    });

    if (existingRenewal) {
      return res.status(400).json({
        error: 'A renewal is already in progress for this purchase',
        code: 'RENEWAL_IN_PROGRESS',
        renewalId: existingRenewal._id,
        transactionId: existingRenewal.transactionId
      });
    }

    // Generate transaction ID
    const transactionId = generateTransactionId('REN');
    const renewalAmount = purchase.policyId.premium;

    // Create renewal record
    const renewal = new Renewal({
      userId,
      purchaseId,
      transactionId,
      status: 'initiated',
      amount: renewalAmount,
      currency: purchase.currency,
      paymentMethod,
      oldExpiryDate: purchase.expiryDate
    });

    await renewal.save();

    logger.info(`Renewal initiated: ${transactionId} for purchase ${purchaseId}`);

    // Process payment asynchronously
    setImmediate(async () => {
      try {
        renewal.status = 'processing';
        await renewal.save();

        const paymentResult = await processPayment({
          amount: renewalAmount,
          currency: purchase.currency,
          paymentMethod,
          transactionId
        });

        if (paymentResult.success) {
          await completeRenewalSuccess(renewal, purchase, paymentResult);
        } else {
          await completeRenewalFailure(renewal, purchase, paymentResult);
        }
      } catch (error) {
        logger.error(`Payment processing error for ${transactionId}:`, error);
        await completeRenewalFailure(renewal, purchase, { error: error.message });
      }
    });

    res.status(202).json({
      success: true,
      message: 'Renewal initiated. Processing payment...',
      renewalId: renewal._id,
      transactionId,
      status: 'processing'
    });

  } catch (error) {
    logger.error('Initiate renewal error:', error);
    res.status(500).json({
      error: 'Failed to initiate renewal',
      code: 'RENEWAL_INITIATION_ERROR'
    });
  }
};

/**
 * Complete renewal on successful payment
 */
const completeRenewalSuccess = async (renewal, purchase, paymentResult) => {
  try {
    // Calculate new expiry date
    // Re-fetch purchase with populated policy to get tenure
    const fullPurchase = await Purchase.findById(purchase._id).populate('policyId');
    if (!fullPurchase || !fullPurchase.policyId) {
      throw new Error('Purchase or policy not found');
    }
    
    const policy = fullPurchase.policyId;
    const newExpiryDate = calculateNewExpiry(purchase.expiryDate, policy.tenure);

    // Update renewal record
    renewal.status = 'success';
    renewal.newExpiryDate = newExpiryDate;
    renewal.gatewayTransactionId = paymentResult.gatewayTransactionId;
    renewal.gatewayReceipt = paymentResult.gatewayReceipt;
    renewal.completedAt = new Date();
    await renewal.save();

    // Update purchase record
    const oldExpiry = purchase.expiryDate;
    purchase.expiryDate = newExpiryDate;
    purchase.renewalStatus = 'renewed';
    purchase.lastRenewedAt = new Date();
    purchase.renewalHistory.push({
      amount: renewal.amount,
      paidAt: new Date(),
      transactionId: renewal.transactionId,
      oldExpiry: oldExpiry,
      newExpiry: newExpiryDate
    });
    await purchase.save();

    // Log to renewals.log
    await logRenewalEvent({
      event: 'RENEWAL_SUCCESS',
      transactionId: renewal.transactionId,
      purchaseId: purchase._id,
      userId: renewal.userId,
      amount: renewal.amount,
      oldExpiry: oldExpiry,
      newExpiry: newExpiryDate,
      timestamp: new Date().toISOString()
    });

    // Send success email
    await sendRenewalSuccessEmail(renewal, purchase, newExpiryDate);

    logger.info(`Renewal completed successfully: ${renewal.transactionId}`);

  } catch (error) {
    logger.error('Error completing renewal:', error);
    throw error;
  }
};

/**
 * Complete renewal on payment failure
 */
const completeRenewalFailure = async (renewal, purchase, paymentResult) => {
  try {
    // Update renewal record
    renewal.status = 'failed';
    renewal.errorMessage = paymentResult.error || paymentResult.message;
    renewal.errorCode = paymentResult.errorCode;
    renewal.completedAt = new Date();
    await renewal.save();

    // Log to renewals.log
    await logRenewalEvent({
      event: 'RENEWAL_FAILED',
      transactionId: renewal.transactionId,
      purchaseId: purchase._id,
      userId: renewal.userId,
      amount: renewal.amount,
      error: renewal.errorMessage,
      timestamp: new Date().toISOString()
    });

    // Send failure email
    await sendRenewalFailureEmail(renewal, purchase);

    logger.warn(`Renewal failed: ${renewal.transactionId}`);

  } catch (error) {
    logger.error('Error handling renewal failure:', error);
    throw error;
  }
};

